import java.io.BufferedReader;
import java.io.InputStreamReader;

public class Solution {
    static long MOD = 998244353L;

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] input = br.readLine().split(" ");
        long n = Long.parseLong(input[0]);
        long m = Long.parseLong(input[1]);
        long l = Long.parseLong(input[2]);
        long r = Long.parseLong(input[3]);

        if ((n * m) % 2 == 1) {
            System.out.println(modularExponentiation(r - l + 1, n * m));
            return;
        }

        long evenCount = r / 2 - (l - 1) / 2;
        long oddCount = (r - l + 1) - evenCount;

        long total = (modularExponentiation(evenCount + oddCount, n * m) + modularExponentiation(evenCount - oddCount, n * m)) % MOD;
        long inv2 = modularExponentiation(2, MOD - 2);
        long answer = (total * inv2) % MOD;

        System.out.println(answer);
    }

    static long modularExponentiation(long base, long exp) {
        long result = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = (result * base) % MOD;
            }
            base = (base * base) % MOD;
            exp >>= 1;
        }
        return result;
    }
}
